import { INicknameState } from '../types';

export class Validator {
    private state: INicknameState;

    constructor(state: INicknameState) {
        this.state = state;
    }

    public validate(nickname: string): void {
        this.checkLength(nickname);
        this.checkStartingCharacter(nickname);
        this.checkAlphaNumeric(nickname);
    }

    private checkLength(nickname: string): void {
        this.state.requirements.length = nickname.length >= this.state.config.minCharacters && nickname.length <= this.state.config.maxCharacters;
    }

    private checkStartingCharacter(nickname: string): void {
        if (nickname.toLowerCase().startsWith(this.state.config.cMIdentifier.toLowerCase()) && nickname.charAt(2)) {
            const regExp = /[a-zA-Z0-9]/;
            this.state.requirements.startingCharacter = regExp.test(nickname.charAt(2));
            return;
        }
        this.state.requirements.startingCharacter = nickname.length !== 0;
    }

    private checkAlphaNumeric(nickname: string): void {
        const regexp = /^(?:\w|[-.,@\\])+$/;
        this.state.requirements.alphaNumeric = (regexp.test(nickname) && nickname.length !== 0);
    }
}